    elif mode == 1:
        a = [draw(st.integers(0, 10))] * n
    elif mode == 2:
        a = sorted(draw(st.lists(st.integers(0, 10), min_size=n, max_size=n)))
    else:
        a = sorted(draw(st.lists(st.integers(0, 10), min_size=n, max_size=n)), reverse=True)
    return f"{n}\n{' '.join(map(str, a))}\n"

def validate(inp):
    lines = inp.strip().split("\n")
    if len(lines) != 2:
        return False
    t = lines[0].split()
    if len(t) != 1:
        return False
    n = int(t[0])
    a_tokens = lines[1].split()
    if len(a_tokens) != n:
        return False
    a = [int(x) for x in a_tokens]
    return (1 <= n <= 5 * 10**5
            and all(0 <= x <= 5 * 10**5 for x in a))

def ref(inp):
    t = inp.split()
    n = int(t[0])
    c = [int(x) for x in t[1:1 + n]]
    # Year i (1-based): alien i becomes adult. Every earlier adult j (1-based, j < i)
    # with at least one stone gives one stone to alien i. Gifts are determined by the
    # stone counts at the start of the event.
    for i in range(1, n + 1):
        givers = [j for j in range(1, i) if c[j - 1] > 0]
        c[i - 1] += len(givers)
        for j in givers:
            c[j - 1] -= 1
    return " ".join(map(str, c))
