    t = inp.split()
    if len(t) < 1:
        return False
    n = int(t[0])
    if not (1 <= n <= 5 * 10**5):
        return False
    if len(t) != 1 + n:
        return False
    a = [int(x) for x in t[1:]]
    return all(0 <= x <= 5 * 10**5 for x in a)

def ref(inp):
    t = inp.split()
    n = int(t[0])
    B = [int(x) for x in t[1:1 + n]]
    # Simulate year by year. At year k (1-indexed), alien k becomes adult.
    # Every earlier adult (indices 0..k-2) with at least one stone gives one stone to alien k-1.
    for k in range(1, n + 1):
        newcomer = k - 1
        givers = [j for j in range(newcomer) if B[j] > 0]
        B[newcomer] += len(givers)
        for j in givers:
            B[j] -= 1
    return " ".join(map(str, B))
